nodes.detail:
• %v 只输出所有的值；
• %+v 先输出字段名字，再输出该字段的值；
• %#v 先输出结构体名字值，再输出结构体（字段名字+字段的值）

ackage main
import "fmt"
type student struct {
    id   int32
    name string
}
func main() {
    a := &student{id: 1, name: "微客鸟窝"}
    fmt.Printf("a=%v  \n", a) // a=&{1 微客鸟窝}  
    fmt.Printf("a=%+v  \n", a) // a=&{id:1 name:微客鸟窝}  
    fmt.Printf("a=%#v  \n", a) // a=&main.student{id:1, name:"微客鸟窝"}
}

